VALUES ('Razorpay', 'razorpay', NULL, NULL, NULL, NULL, NULL, '[{"url": "https://www.techprep.app/blog/razorpay-interview-process", "title": "Razorpay interview process (TechPrep, 2026)"}, {"url": "https://www.designgurus.io/answers/detail/what-is-the-razorpay-interview-process-like-round-by-round", "title": "Razorpay interview process, round by round (DesignGurus)"}]'::jsonb, '2026-10-15');

INSERT INTO company_role_patterns (company_id, role_family, level, rounds, topic_slugs, notes, experience_summary, pay, difficulty_level, difficulty_basis, sources, last_checked)
SELECT id, 'software_engineer', 'all levels', '[{"name": "Recruiter screen", "format": "Introductory call", "tests": "Background, current role and motivation", "duration": "15 to 30 minutes"}, {"name": "Online assessment", "format": "Proctored test on HackerEarth or Evaluate", "tests": "Two or three data structures and algorithms problems plus multiple-choice questions", "duration": "90 to 120 minutes"}, {"name": "Machine coding", "format": "Live coding session", "tests": "A modular working system built from scratch; compilable code is expected", "duration": "60 to 90 minutes"}, {"name": "High-level design", "format": "Whiteboard-style, mainly for SDE-2 and above", "tests": "Architecture, scalability, fault tolerance and trade-offs", "duration": "60 minutes"}, {"name": "Hiring manager", "format": "Conversation", "tests": "Past projects, technology decisions, conflict and failure", "duration": "45 to 60 minutes"}, {"name": "HR", "format": "Short call", "tests": "Compensation and culture", "duration": "15 to 30 minutes"}]'::jsonb, '["arrays", "hashing", "oop_principles", "system_design_fundamentals", "sql_fundamentals", "behavioural_storytelling"]'::jsonb, 'Neither source states an interview year; one is titled 2026.', 'Both sources give four to six rounds over two to four weeks, but the second one gives durations that differ in places, for example the online test lasting up to three hours for one experienced candidate. The campus path is reported as two technical rounds, a managerial round and a short HR round.', NULL, NULL, NULL, '[{"url": "https://www.techprep.app/blog/razorpay-interview-process", "title": "Razorpay interview process (TechPrep, 2026)"}, {"url": "https://www.designgurus.io/answers/detail/what-is-the-razorpay-interview-process-like-round-by-round", "title": "Razorpay interview process, round by round (DesignGurus)"}]'::jsonb, '2026-10-15'
FROM company_profiles WHERE slug = 'razorpay';

