INSERT INTO company_role_patterns (company_id, role_family, level, rounds, topic_slugs, notes, experience_summary, pay, difficulty_level, difficulty_basis, sources, last_checked)
SELECT id, 'software_engineer', 'all levels', '[{"name": "First interview", "format": "Offline at the Gurgaon office", "tests": "Open-ended discussion leading to a graph problem on topological sorting", "duration": null}, {"name": "Second interview", "format": "Discussion", "tests": "Competitive programming achievements, internship experience, databases and computer networks", "duration": null}, {"name": "HR round", "format": "Relaxed discussion with a senior manager", "tests": "Future goals and reasons for joining", "duration": null}, {"name": "Last round", "format": "Discussion with the CTO", "tests": "Competitive programming results and college projects", "duration": null}]'::jsonb, '["graphs", "sql_fundamentals", "networking_basics", "behavioural_storytelling"]'::jsonb, NULL, 'This is a single reported account, last updated in July 2023 on the site, for a candidate who found the role through a referral. It does not say whether an offer was made, so it should be read as one person''s path only.', NULL, NULL, NULL, '[{"url": "https://www.geeksforgeeks.org/?p=1038792", "title": "Zomato interview experience for software engineer (GeeksforGeeks)"}]'::jsonb, '2026-10-15'
FROM company_profiles WHERE slug = 'zomato';

