INSERT INTO company_role_patterns (company_id, role_family, level, rounds, topic_slugs, notes, experience_summary, pay, difficulty_level, difficulty_basis, sources, last_checked)
SELECT id, 'software_engineer', 'all levels', '[{"name": "Online assessment", "format": "HackerRank or HackerEarth", "tests": "Coding at medium difficulty, sometimes one SQL question", "duration": "75 to 90 minutes"}, {"name": "Machine coding", "format": "Build a working program, no outside code", "tests": "Whether it runs, class design and extensibility", "duration": "About 120 minutes"}, {"name": "Problem solving", "format": "Live coding", "tests": "Data structures, algorithms, and time and space cost", "duration": "About 60 minutes"}, {"name": "Design", "format": "Discussion", "tests": "Low-level design for SDE-1 and SDE-2, system design for senior roles", "duration": "30 to 60 minutes"}, {"name": "Hiring manager", "format": "Conversation", "tests": "Ownership, past projects and systems fundamentals", "duration": "30 to 60 minutes"}, {"name": "HR", "format": "Call", "tests": "Motivation, notice period and logistics", "duration": "20 to 30 minutes"}]'::jsonb, '["arrays", "sql_fundamentals", "oop_principles", "system_design_fundamentals", "behavioural_storytelling"]'::jsonb, NULL, 'The source reports four to six rounds over about two to six weeks and gives no year. A reported campus path has a 90-minute test, a one-hour technical interview and a 30-minute managerial round, with no machine coding round.', NULL, 3, 'The source describes the online assessment as medium-difficulty coding.', '[{"url": "https://www.designgurus.io/answers/detail/what-is-the-swiggy-interview-process-like-round-by-round", "title": "Swiggy interview process, round by round (DesignGurus)"}]'::jsonb, '2026-10-15'
FROM company_profiles WHERE slug = 'swiggy';

