INSERT INTO company_role_patterns (company_id, role_family, level, rounds, topic_slugs, notes, experience_summary, pay, difficulty_level, difficulty_basis, sources, last_checked)
SELECT id, 'software_engineer', 'all levels', '[{"name": "Online coding test", "format": "Proctored HackerRank test, three problems", "tests": "Data structures and algorithms; reported topics include greedy logic, bitmask dynamic programming and combinatorics", "duration": "90 to 105 minutes"}, {"name": "Project or machine coding", "format": "Working program from written requirements, reviewed afterwards", "tests": "Whether it runs, class design and ease of adding a requirement", "duration": "About 150 minutes"}, {"name": "Technical interview 1", "format": "Live video", "tests": "Medium-difficulty problem solving, CS fundamentals and past projects", "duration": "75 to 90 minutes"}, {"name": "Technical interview 2", "format": "Live video", "tests": "Low-level design, or system design for senior levels", "duration": "75 to 90 minutes"}, {"name": "Culture fit or managerial", "format": "Video conversation, often with a senior engineering leader", "tests": "Ownership, communication, values and career direction", "duration": "About 60 minutes"}]'::jsonb, '["arrays", "dynamic_programming", "oop_principles", "system_design_fundamentals", "behavioural_storytelling"]'::jsonb, NULL, 'The source gives four to six rounds and no year. Its campus path has a grade filter followed by a single technical interview focused more on fundamentals; one campus report says about 200 candidates took the test and about 20 advanced.', NULL, 3, 'The source describes the first technical interview as medium-difficulty problem solving.', '[{"url": "https://www.designgurus.io/answers/detail/what-is-the-cred-interview-process-like-round-by-round", "title": "CRED interview process, round by round (DesignGurus)"}]'::jsonb, '2026-10-15'
FROM company_profiles WHERE slug = 'cred';

