INSERT INTO company_role_patterns (company_id, role_family, level, rounds, topic_slugs, notes, experience_summary, pay, difficulty_level, difficulty_basis, sources, last_checked)
SELECT id, 'software_engineer', 'all levels', '[{"name": "AI-based screening", "format": "Verbal problem solving judged by an AI tool", "tests": "Reasoning questions", "duration": null}, {"name": "Online coding round", "format": "HackerRank, three problems", "tests": "Coding problems such as a longest common subsequence variation and deque problems", "duration": "105 minutes"}, {"name": "Low-level design", "format": "Design discussion", "tests": "An inventory management system with OOP implementation, then database schema and OOP principles", "duration": null}, {"name": "Hiring manager", "format": "Interview", "tests": "Resume, previous experience, technology trends and motivation", "duration": null}]'::jsonb, '["arrays", "dynamic_programming", "oop_principles", "sql_fundamentals", "behavioural_storytelling"]'::jsonb, 'The page quotes a fresher salary range from other review sites without a year, so no pay figure is recorded.', 'The page was updated in October 2025 and describes the intern and trainee path above. For experienced candidates it reports an online test with three medium-to-hard questions, a 1.5 hour design interview and a 40 minute managerial interview. The whole process is said to take two to four weeks.', NULL, 4, 'The page describes the experienced path online test as three medium-to-hard coding questions.', '[{"url": "https://www.placementpreparation.io/blog/?p=17256", "title": "Meesho recruitment process (placementpreparation.io, updated October 2025)"}]'::jsonb, '2026-10-15'
FROM company_profiles WHERE slug = 'meesho';

