INSERT INTO company_role_patterns (company_id, role_family, level, rounds, topic_slugs, notes, experience_summary, pay, difficulty_level, difficulty_basis, sources, last_checked)
SELECT id, 'software_engineer', 'all levels', '[{"name": "Recruiter call", "format": "Phone", "tests": "Background, role fit and notice period", "duration": "20 to 30 minutes"}, {"name": "Online assessment", "format": "Timed remote test", "tests": "Multiple-choice questions on complexity, operating systems and threading, plus a programming problem", "duration": null}, {"name": "Data structures round", "format": "Live, one or two rounds", "tests": "Problem solving and running time; reported problems include topological sort, loop detection and lowest common ancestor", "duration": "About 60 minutes each"}, {"name": "Machine coding", "format": "Timed build of a small console program, reported for experienced candidates", "tests": "Whether it runs, class organisation and room for new requirements", "duration": "90 minutes to 2 hours"}, {"name": "System design", "format": "Open discussion", "tests": "High-level design and trade-offs", "duration": "About 60 minutes"}, {"name": "Hiring manager", "format": "Conversation", "tests": "Ownership, project depth and reason for the move", "duration": "30 to 60 minutes"}]'::jsonb, '["arrays", "linked_lists", "graphs", "trees", "stacks", "caching_strategies", "system_design_fundamentals", "behavioural_storytelling"]'::jsonb, NULL, 'The source says Groww does not publish a round list, so this is reported by candidates. It gives four to six rounds over two to three weeks and no year. Freshers do not report machine coding or system design rounds.', NULL, NULL, NULL, '[{"url": "https://www.designgurus.io/answers/detail/what-is-the-groww-interview-process-like-round-by-round", "title": "Groww interview process, round by round (DesignGurus)"}]'::jsonb, '2026-10-15'
